// GENERATED by scripts/sync-shared.mjs from the web app — do not edit; run `npm run sync:shared`.
// The one definition of a player's clue text. The engines store exactly this, and the server moderates exactly this,
// so nothing can reach other players' phones without being checked.
export const CLUE_MAX = 40;

/**
 * Whitespace collapsed, ends trimmed, capped. Anything but a string counts as no clue. Interior spaces survive as one
 * space, so a game that wants one word (Say Less) can still see and refuse two.
 */
export const normalizeClue = (text: unknown): string =>
  typeof text === "string"
    ? text.replace(/\s+/g, " ").trim().slice(0, CLUE_MAX)
    : "";
